import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAnimation } from './AnimationQueue';

interface AnimatedTextProps {
  text: string;
  element?: 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div' | 'li' | 'a';
  className?: string;
  preserveWhitespace?: boolean;
  onComplete?: () => void;
  delay?: number;
  priority?: number; // Add priority for the queue
  dependencies?: string[]; // Add dependencies for the queue
}

/**
 * AnimatedText component that renders text character by character
 * Uses the animation queue system for coordinated animations
 */
const AnimatedText: React.FC<AnimatedTextProps> = ({
  text,
  element = 'span',
  className = '',
  preserveWhitespace = false,
  onComplete,
  delay = 0,
  priority = 0,
  dependencies = []
}) => {
  const [visibleChars, setVisibleChars] = useState(0);
  const [isComplete, setIsComplete] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  const animationIdRef = useRef<string | null>(null);

  // Get animation context
  const { registerAnimation, completeAnimation } = useAnimation();

  // Register with animation queue on mount
  useEffect(() => {
    if (!text) return;

    // Clean up whitespace if not preserving it
    const processedText = preserveWhitespace ? text : text.replace(/\s+/g, ' ').trim();

    const handleStart = () => {
      setVisibleChars(0);
      setIsComplete(false);
      setIsAnimating(true);
    };

    const handleComplete = () => {
      if (onComplete) {
        onComplete();
      }
    };

    // Register this animation with the queue
    const animationId = registerAnimation('text', {
      priority,
      dependencies,
      onStart: handleStart,
      onComplete: handleComplete
    });

    animationIdRef.current = animationId;

    // Clean up
    return () => {
      if (animationIdRef.current && isAnimating && !isComplete) {
        completeAnimation(animationIdRef.current);
      }
    };
  }, [text, priority, dependencies, preserveWhitespace, registerAnimation, completeAnimation, onComplete]);

  // Handle actual animation when active
  useEffect(() => {
    if (!isAnimating || !animationIdRef.current) return;

    const processedText = preserveWhitespace ? text : text.replace(/\s+/g, ' ').trim();
    let timeout: NodeJS.Timeout;
    let charIndex = 0;

    const animateNextChar = () => {
      if (charIndex < processedText.length) {
        charIndex++;
        setVisibleChars(charIndex);

        // Calculate next delay - longer for punctuation
        let charDelay = 30; // Base delay in ms

        // Slow down for punctuation
        const currentChar = processedText[charIndex - 1];
        if (['.', '!', '?', ',', ';', ':'].includes(currentChar)) {
          charDelay = 150; // Longer pause after punctuation
        }

        // Small random variation
        charDelay += Math.random() * 20 - 10;

        // Add any external delay
        const totalDelay = charDelay + (charIndex === 1 ? delay : 0);

        timeout = setTimeout(animateNextChar, totalDelay);
      } else {
        setIsComplete(true);
        setIsAnimating(false);

        // Signal completion to the animation queue
        if (animationIdRef.current) {
          completeAnimation(animationIdRef.current);
        }
      }
    };

    // Start the animation sequence
    timeout = setTimeout(animateNextChar, 50);

    return () => clearTimeout(timeout);
  }, [text, delay, isAnimating, preserveWhitespace, completeAnimation]);

  // Create array of characters with animated wrappers
  const processedText = preserveWhitespace ? text : text.replace(/\s+/g, ' ').trim();
  const animatedChars = processedText.split('').map((char, index) => {
    const isVisible = index < visibleChars;

    return (
      <AnimatePresence key={index} mode="wait">
        {isVisible && (
          <motion.span
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.1 }}
            style={{ 
              display: 'inline-block',
              whiteSpace: preserveWhitespace ? 'pre' : 'normal'
            }}
          >
            {char}
          </motion.span>
        )}
      </AnimatePresence>
    );
  });

  // Component-specific styles
  const componentStyle = {
    display: 'block',
    width: '100%',
    whiteSpace: preserveWhitespace ? 'pre-wrap' as const : 'normal' as const,
    wordBreak: 'break-word' as const
  };

  // Render with specified element type
  const Component = element as any;

  return (
    <Component 
      className={`animated-text ${className} ${isComplete ? 'complete' : ''}`}
      style={componentStyle}
    >
      {animatedChars}
    </Component>
  );
};

export default AnimatedText;
